user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses one or more intended future actions or an ordered sequence of actions that the agent intends to carry out.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node containing the intended future action or sequence of actions."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one action or step to be performed in the future.",
      "The intended action is presented as something the agent will do, rather than as a completed or merely possible action."
    ],
    "exclusion_conditions": [
      "The reasoning only reports actions already completed or observations already obtained.",
      "The reasoning states a general goal without identifying any intended action or step."
    ]
  },
  {
    "name": "DECOMPOSES_TASK_INTO_SUBGOALS",
    "definition": "The reasoning breaks an overall task into multiple distinct, ordered subgoals or steps that can guide subsequent execution.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that decomposes the task into subgoals or steps."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least two distinct subgoals, questions, or procedural steps.",
      "The subgoals or steps are presented with an ordering, dependency, or execution relationship rather than as an unrelated collection."
    ],
    "exclusion_conditions": [
      "The reasoning identifies only a single intended action or subgoal.",
      "The reasoning merely restates the overall task without dividing it into executable parts."
    ]
  },
  {
    "name": "OPERATIONALIZES_UNDERSPECIFIED_REQUIREMENT",
    "definition": "The reasoning interprets an ambiguous or underspecified requirement by selecting or defining a concrete, measurable interpretation or procedure that can be executed.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that resolves an ambiguity by defining an operational interpretation."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies an ambiguity, an alternative reading, or an underspecified aspect of the requirement.",
      "The reasoning commits to a concrete operational definition, such as specific fields to process, a filter condition, a metric, or a tool to use.",
      "The selected interpretation is sufficiently specific to guide an executable procedure."
    ],
    "exclusion_conditions": [
      "The requirement is already fully specified and the reasoning only restates it.",
      "The reasoning notes ambiguity but does not resolve it into an operational definition.",
      "The reasoning provides procedural detail that is not tied to interpreting the requirement."
    ]
  },
  {
    "name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
    "definition": "The reasoning draws a conclusion or updates its understanding using identifiable content from the observation as supporting evidence.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node expressing a conclusion or updated belief based on the observation."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation supplying the evidence used in the conclusion."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a conclusion, inference, or updated understanding.",
      "Identifiable content from the observation supports or justifies that conclusion.",
      "The relationship between the observation content and the conclusion is explicit enough to identify the evidential link."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats the observation without drawing an inference or conclusion.",
      "The observation is unrelated to the stated conclusion or provides no identifiable support."
    ]
  },
  {
    "name": "REVISES_APPROACH_IN_RESPONSE_TO_FAILED_ATTEMPT",
    "definition": "An observation reports a failed or unexpected outcome; the reasoning acknowledges or diagnoses the problem and selects an alternative approach; the revised action implements that alternative rather than repeating the failed attempt.",
    "parameters": [
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The observation reporting the error, failed retrieval, or unexpected result."
      },
      {
        "name": "diagnostic_reasoning",
        "type": "reasoning",
        "description": "The reasoning that acknowledges or diagnoses the failure and selects an alternative approach."
      },
      {
        "name": "revised_action",
        "type": "action",
        "description": "The action implementing the alternative approach after the diagnosed failure."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error, failed retrieval, or unexpected result relative to the attempted operation.",
      "The reasoning acknowledges the problem and identifies or selects an alternative course of action.",
      "The revised action is consistent with the alternative approach and differs from the failed attempt."
    ],
    "exclusion_conditions": [
      "The observation reports an expected successful result rather than a failure or unexpected outcome.",
      "The reasoning only restates the failure without selecting or proposing an alternative approach.",
      "The revised action is unrelated to the diagnosis or merely repeats the failed operation."
    ]
  },
  {
    "name": "REMEDIES_MISSING_CAPABILITY",
    "definition": "The reasoning identifies an absent dependency, tool, or capability required for the task; a provisioning action supplies or installs it; an observation confirms that the required capability is available.",
    "parameters": [
      {
        "name": "gap_reasoning",
        "type": "reasoning",
        "description": "The reasoning node identifying the missing dependency, tool, or capability."
      },
      {
        "name": "provisioning_action",
        "type": "action",
        "description": "The action that installs, supplies, or otherwise provisions the identified capability."
      },
      {
        "name": "confirmation_observation",
        "type": "observation",
        "description": "The observation confirming that the capability has been provisioned or is available."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific dependency, tool, or capability as missing and required for the task.",
      "The provisioning action is directed at supplying or installing that identified capability.",
      "The confirmation observation reports successful installation or availability of the capability."
    ],
    "exclusion_conditions": [
      "No specific missing dependency, tool, or capability is identified.",
      "The action does not provision the identified capability.",
      "The observation does not confirm availability, or the installation outcome is left unknown."
    ]
  },
  {
    "name": "TRANSLATES_SCHEMA_EVIDENCE_INTO_PROCESSING_PROCEDURE",
    "definition": "An observation provides structural or schema information about a resource; the reasoning uses that information to determine the fields or procedure needed for the task; the action creates an executable artifact or command implementing that procedure.",
    "parameters": [
      {
        "name": "schema_observation",
        "type": "observation",
        "description": "The observation containing schema, field, format, or documented layout information."
      },
      {
        "name": "interpretation_reasoning",
        "type": "reasoning",
        "description": "The reasoning that maps the task requirements onto the fields or procedure indicated by the schema evidence."
      },
      {
        "name": "implementation_action",
        "type": "action",
        "description": "The action creating a script, command, or other executable artifact that implements the determined procedure."
      }
    ],
    "assertion_conditions": [
      "The observation contains structural, schema, field-list, format, or documented layout information relevant to the resource.",
      "The reasoning explicitly uses this structural information to determine which fields, parameters, or procedure are needed for the task.",
      "The action creates or executes a procedure that operationalizes the interpretation, rather than merely retrieving or inspecting data."
    ],
    "exclusion_conditions": [
      "The observation contains only values or results without structural or schema information.",
      "The reasoning does not reference the schema or field information when determining the procedure.",
      "The action retrieves or inspects data but does not implement a procedure derived from the schema evidence."
    ]
  },
  {
    "name": "SURVEYS_ENVIRONMENT_STATE_FOR_PLANNING",
    "definition": "A reconnaissance action inspects unknown environment or resource state because the reasoning indicates that this state is relevant to planning; the resulting observation reveals state that can inform subsequent decisions.",
    "parameters": [
      {
        "name": "planning_reasoning",
        "type": "reasoning",
        "description": "The reasoning node indicating that environment or resource state is unknown or relevant to planning."
      },
      {
        "name": "exploratory_action",
        "type": "action",
        "description": "The action performing an inspection, listing, or query of the environment or resource state."
      },
      {
        "name": "state_observation",
        "type": "observation",
        "description": "The observation reporting the inspected environment or resource state."
      }
    ],
    "assertion_conditions": [
      "The reasoning indicates that some environment or resource state is unknown, must be checked, or is relevant to planning.",
      "The exploratory action inspects, lists, or queries that environment or resource state.",
      "The observation reports state information relevant to subsequent planning or decisions."
    ],
    "exclusion_conditions": [
      "The action performs a substantive transformation or final computation rather than an inspection of state.",
      "The reasoning already has the relevant state and expresses no reconnaissance need.",
      "The observation is unrelated to the environment or resource state being surveyed."
    ]
  }
]

Existing registry:
[
  {
    "name": "PLANS_NEXT_ACTION",
    "definition": "The reasoning explicitly expresses an intended future action or sequence of actions that the agent has not yet performed.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that states an intended future action or sequence."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one intended future action or step.",
      "The intended action is presented as something still to be done rather than as already completed."
    ],
    "exclusion_conditions": [
      "The reasoning only reports or summarizes actions already completed.",
      "The reasoning states a conclusion, diagnosis, or observation summary without expressing future intent."
    ]
  },
  {
    "name": "IDENTIFIES_DEFECT_FROM_OBSERVATION",
    "definition": "The reasoning uses identifiable content of an observation to identify a defect, error, or incompleteness in the artifact or state described by that observation.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that identifies the defect, error, or gap."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation whose content provides evidence of the defective or incomplete state."
      }
    ],
    "assertion_conditions": [
      "The observation contains identifiable evidence of an incomplete, erroneous, or otherwise defective state.",
      "The reasoning explicitly characterizes that state as a problem, gap, or defect requiring attention or correction."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats or describes the observation without identifying a defect.",
      "The observation does not contain evidence of a defect or gap.",
      "The reasoning asserts a defect that is not supported by identifiable observation content."
    ]
  },
  {
    "name": "FORMULATES_CORRECTIVE_SOLUTION",
    "definition": "The reasoning derives and specifies a concrete method, content, or set of steps intended to remedy an identified defect or gap.",
